pragma solidity >=0.8.0;

contract StringBytesConcatProbe {
    event Dyn(string indexed marker, string val, bytes data);

    uint256 public emitCount;
    string public lastVal;
    bytes public lastData;

    function log(string memory marker, string memory a, string memory b, bytes memory x, bytes memory y) external {
        emitCount += 1;
        lastVal = string.concat(a, b);
        lastData = bytes.concat(x, y);
        emit Dyn(marker, lastVal, lastData);
    }
}
